看下这个   GoRoute(
        path: DeviceSearchRoutePaths.addOpen,
        builder: (context, state) {
          final scanContext = ProviderScope.containerOf(
            context,
            listen: false,
          ).read(deviceScanBusinessContextProvider);
          final heroAsset = scanContext?.productId == 25
              ? DeviceSearchAssetPaths.shootingHeadphonesOpen
              : DeviceSearchAssetPaths.openDevice;
          final l10n = DeviceSearchL10n.of(context);
          return _withDiscoveryFence(
            DeviceAddOpenPage(
              heroAsset: heroAsset,
              title: scanContext?.productId == 25
                  ? l10n.addOpenCameraHeadsetTitle
                  : null,
              description: scanContext?.productId == 25
                  ? l10n.addOpenCameraHeadsetHint
                  : null,
              readyLabel: scanContext?.productId == 25
                  ? l10n.addOpenCameraHeadsetReadyButton
                  : null,
              onReady: () => context.push(DeviceSearchRoutePaths.search),
            ),
          );
        },
      ), 

